//! Fortran (F2008, gfortran): the `azul` module (generated by
//! `doc/src/codegen/v2/lang_fortran`, `use azul`).
//!
//! Spellings: the raw layer names every C function in snake_case
//! (`AzCssProperty_textColor` -> `az_css_property_text_color`; past 63
//! characters the separators collapse, then a hash tail), types keep their
//! C names (`type(AzColorU)`), C-like enum constants are `<Enum>_<Variant>`
//! integer parameters (`LayoutDisplay_Flex`); structs are structure
//! constructors with keyword arguments whose field names are escaped
//! (`AzColorU(r_=-1_c_int8_t, ..)`: u8 is `c_int8_t`, so 255 is -1);
//! strings are `azul_string('..')`.
//!
//! Calls and constructors nest; a Vec needs a `target` array
//! ([`super::linear`]): `az_x_vec_copy_from_ptr(c_loc(t1(1)), n_c_size_t)`.
//! Limitation: tagged unions are ABI-opaque blobs in these bindings
//! (`integer(c_int32_t) :: opaque_(n)`), so a `CssPropertyValue<T>` alias
//! or a `CssProperty` without a constructor cannot be built by hand.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::variant_ctor_method,
    CodegenBackend, GeneratedFile,
};

/// The Fortran printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Fortran;

const MAX_IDENT_LEN: usize = 63;

/// `is_fortran_reserved` of `lang_fortran/mod.rs`.
const RESERVED: &[&str] = &[
    "if", "then", "else", "elseif", "endif", "do", "enddo", "end", "function", "subroutine",
    "module", "program", "type", "interface", "use", "implicit", "real", "integer", "logical",
    "character", "complex", "double", "precision", "kind", "len", "where", "elsewhere",
    "endwhere", "select", "case", "default", "endselect", "go", "goto", "continue", "stop",
    "return", "call", "pure", "elemental", "recursive", "result", "contains", "private",
    "public", "protected", "save", "data", "block", "common", "equivalence", "namelist",
    "external", "intrinsic", "optional", "parameter", "pointer", "target", "allocatable",
    "dimension", "intent", "in", "out", "inout", "value", "volatile", "asynchronous", "bind",
    "import", "abstract", "class", "deferred", "extends", "final", "generic", "non_overridable",
    "nopass", "pass", "procedure", "sequence", "abs", "min", "max", "size", "data_", "r",
];

/// `truncate_identifier` of `lang_fortran/mod.rs`.
fn truncate(name: &str) -> String {
    if name.len() <= MAX_IDENT_LEN {
        return name.to_string();
    }
    let head: String = name.chars().take(MAX_IDENT_LEN - 9).collect();
    let mut hash: u32 = 0x811c_9dc5;
    for b in name.bytes() {
        hash ^= u32::from(b);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    format!("{head}_{hash:08x}")
}

/// `sanitize_identifier` of `lang_fortran/mod.rs`.
fn sanitize(name: &str) -> String {
    let out = if RESERVED.contains(&name.to_lowercase().as_str()) {
        format!("{name}_")
    } else if name.starts_with('_') {
        format!("f{name}")
    } else {
        name.to_string()
    };
    truncate(&out)
}

/// `pascal_to_snake_case` of `lang_fortran/mod.rs`.
fn pascal_to_snake(s: &str) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// `fortran_alias_for` of `lang_fortran/functions.rs`: the Fortran name of
/// C symbol `Az<Class>_<method>`.
fn alias(c_symbol: &str) -> String {
    let snake = pascal_to_snake(c_symbol);
    if snake.len() <= MAX_IDENT_LEN {
        return snake;
    }
    if let Some((class, method)) = c_symbol.split_once('_') {
        let class = class.to_ascii_lowercase();
        for candidate in [
            format!("{class}_{}", pascal_to_snake(method)),
            format!("{class}_{}", method.to_ascii_lowercase()),
            format!("{class}{}", method.to_ascii_lowercase()),
        ] {
            if candidate.len() <= MAX_IDENT_LEN {
                return candidate;
            }
        }
    }
    truncate(&snake)
}

fn apply(f: &str, args: &[String]) -> String {
    format!("{f}({})", args.join(", "))
}

/// A Fortran character literal (quote doubled); other non-printable bytes
/// are concatenated as `achar(n)`.
fn fortran_string(s: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut run = String::new();
    for b in s.bytes() {
        if (0x20..0x7f).contains(&b) {
            if b == b'\'' {
                run.push_str("''");
            } else {
                run.push(char::from(b));
            }
        } else {
            if !run.is_empty() || parts.is_empty() {
                parts.push(format!("'{run}'"));
                run.clear();
            }
            parts.push(format!("achar({b})"));
        }
    }
    if !run.is_empty() || parts.is_empty() {
        parts.push(format!("'{run}'"));
    }
    parts.join(" // ")
}

impl LinearSyntax for Fortran {
    fn int(&self, value: i128, ty: Prim) -> String {
        // no unsigned kinds: u8/u16/u32/u64 wrap into the signed kind
        let (v, kind) = match ty {
            Prim::U8 => (if value > 127 { value - 256 } else { value }, "c_int8_t"),
            Prim::I8 => (value, "c_int8_t"),
            Prim::U16 => (if value > 32_767 { value - 65_536 } else { value }, "c_int16_t"),
            Prim::I16 => (value, "c_int16_t"),
            Prim::U32 => (
                if value > 2_147_483_647 {
                    value - 4_294_967_296
                } else {
                    value
                },
                "c_int32_t",
            ),
            Prim::I32 => (value, "c_int32_t"),
            Prim::U64 | Prim::I64 => (value, "c_int64_t"),
            Prim::Usize => (value, "c_size_t"),
            Prim::Isize => (value, "c_intptr_t"),
            Prim::F32 | Prim::F64 | Prim::Bool => (value, "c_int"),
        };
        format!("{v}_{kind}")
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        format!("{text}_{}", if ty == Prim::F64 { "c_double" } else { "c_float" })
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { ".true._c_bool" } else { ".false._c_bool" })
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        sanitize(&format!("{ty}_{variant}"))
    }

    fn type_name(&self, ty: &str) -> String {
        format!("type(Az{ty})")
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("ARRAY {n} type(Az{elem})")
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let e = self.call_expr(class, method, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let e = self.variant_expr(ty, variant, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn union(
        &self,
        target: &str,
        _ty: &str,
        _variant: &str,
        _tag: usize,
        _payload: Option<&str>,
    ) -> Vec<String> {
        // unreachable: `limitation` rejects every hand-built union
        vec![format!("{target}%opaque_ = 0")]
    }

    fn set_field(&self, target: &str, _ty: &str, field: &str, value: &str) -> String {
        format!("{target}%{} = {value}", sanitize(field))
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("{arr}({}) = {value}", index + 1)
    }

    fn vec_from_array(&self, target: &str, ty: &str, elem: &str, arr: &str, count: &str) -> Vec<String> {
        let e = self.vec_expr(ty, elem, arr, count).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("{target} = {}()", alias(&format!("Az{ty}_create")))]
    }

    fn string(&self, target: &str, s: &str) -> Vec<String> {
        vec![format!("{target} = azul_string({})", fortran_string(s))]
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "`{ty}` is an ABI-opaque blob in the Fortran bindings (no constructor)"
            )),
            Expr::Float { text, .. } if text == "nan" || text.ends_with("inf") => {
                Some("NaN / infinity has no Fortran literal".to_string())
            }
            _ => None,
        }
    }

    fn call_expr(&self, class: &str, method: &str, args: &[String]) -> Option<String> {
        let f = alias(&format!("Az{class}_{}", snake_to_lower_camel(method)));
        Some(apply(&f, args))
    }

    fn variant_expr(&self, ty: &str, variant: &str, args: &[String]) -> Option<String> {
        let f = alias(&format!("Az{ty}_{}", variant_ctor_method(variant)));
        Some(apply(&f, args))
    }

    fn struct_expr(&self, ty: &str, fields: &[(String, String)]) -> Option<String> {
        let fields: Vec<String> = fields
            .iter()
            .map(|(k, v)| format!("{}={v}", sanitize(k)))
            .collect();
        Some(format!("Az{ty}({})", fields.join(", ")))
    }

    fn string_expr(&self, s: &str) -> Option<String> {
        Some(format!("azul_string({})", fortran_string(s)))
    }

    fn vec_expr(&self, ty: &str, _elem: &str, arr: &str, count: &str) -> Option<String> {
        let f = alias(&format!("Az{ty}_copyFromPtr"));
        Some(format!("{f}(c_loc({arr}(1)), {count})"))
    }

    fn vec_empty_expr(&self, ty: &str) -> Option<String> {
        Some(format!("{}()", alias(&format!("Az{ty}_create"))))
    }
}

fn fn_name(item: &Item) -> String {
    sanitize(&item.name.snake())
}

fn item_fn(item: &Item) -> (bool, String) {
    let name = fn_name(item);
    if let Some(reason) = item_blocker(&Fortran, item) {
        return (
            false,
            format!("  ! {name}: not expressible with the Fortran bindings: {reason}\n"),
        );
    }
    let st = lower_to_statements(&Fortran, &item.value);
    let mut out = String::new();
    for line in linear_comments(item, &st) {
        out.push_str(&format!("  ! {line}\n"));
    }
    out.push_str(&format!(
        "  function {name}() result(r)\n    type(Az{}) :: r\n",
        item.ty
    ));
    for (n, t) in &st.decls {
        match t.strip_prefix("ARRAY ") {
            Some(rest) => {
                let (len, ty) = rest.split_once(' ').unwrap_or((rest, ""));
                out.push_str(&format!("    {ty}, target :: {n}({len})\n"));
            }
            None => out.push_str(&format!("    {t} :: {n}\n")),
        }
    }
    for s in &st.body {
        out.push_str(&format!("    {s}\n"));
    }
    out.push_str(&format!("    r = {}\n  end function {name}\n", st.result));
    (true, out)
}

impl CodegenBackend for Fortran {
    fn lang(&self) -> &'static str {
        "fortran"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["f90", "gfortran"]
    }

    fn display_name(&self) -> &'static str {
        "Fortran"
    }

    fn extension(&self) -> &'static str {
        "f90"
    }

    fn emit_module(&self, m: &Module) -> String {
        let fns: Vec<(bool, String, String)> = m
            .items
            .iter()
            .map(|i| {
                let (ok, body) = item_fn(i);
                (ok, fn_name(i), body)
            })
            .collect();
        let mut out = String::from(
            "! Generated by azul-css codegen (Fortran). Do not edit by hand.\n! Compile with \
             -ffree-line-length-none (like the azul modules).\nmodule azul_styles\n  use \
             azul\n  implicit none\n  private\n",
        );
        for (ok, name, _) in &fns {
            if *ok {
                out.push_str(&format!("  public :: {name}\n"));
            }
        }
        out.push_str("\ncontains\n");
        for (_, _, body) in &fns {
            out.push('\n');
            out.push_str(body);
        }
        out.push_str("\nend module azul_styles\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let built: Vec<&Item> = m.items.iter().filter(|i| item_fn(i).0).collect();
        let mut main = String::from(
            "! Build the azul modules first (target/codegen/fortran: make), then:\n!   gfortran \
             -ffree-line-length-none styles.f90 main.f90 azul*.o -L. -lazul -o main && \
             ./main\nprogram main\n  use azul\n  use azul_styles\n  implicit none\n",
        );
        for item in &built {
            main.push_str(&format!(
                "  type(Az{}) :: {}_value\n",
                item.ty,
                fn_name(item)
            ));
        }
        main.push('\n');
        for item in &built {
            let name = fn_name(item);
            main.push_str(&format!(
                "  {name}_value = {name}()\n  print '(A, I0, A)', '{name}: ', {name}_value%len_, \
                 ' properties'\n"
            ));
        }
        main.push_str("end program main\n");
        vec![
            GeneratedFile {
                path: "styles.f90".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.f90".to_string(),
                contents: main,
            },
        ]
    }
}
